use host;
fn main() {
    status := host::write_file(view("w.txt"), view("windows-io"));
    assert(status == 0);
    contents := host::read_file(view("w.txt"));
    host::print(view(contents));
    println(contents.len());
}

struct Point {
    x: u64,
    y: u64,
}
fn main() -> u64 {
    p := Point { x: 3, y: 4 };
    return p.x + p.y;
}

use host;
fn main() {
    println(host::argc() - 1);
    mut i = 1;
    while i < host::argc() {
        host::print(host::arg(i));
        println();
        i += 1;
    }
}

unsafe module runtime;
fn worker(arg: u64, unused: u64) -> u64 {
    raw_store(arg, 42);
    return 0;
}
fn main() -> u64 {
    p := rt_alloc(8);
    raw_store(p, 0);
    h := rt_thread_spawn(worker, p);
    rt_thread_join(h);
    println(raw_load(p));
    rt_free(p);
    return 0;
}

unsafe module runtime;
fn producer(arg: u64, unused: u64) -> u64 {
    raw_store(arg, 7);
    rt_syscall(202, arg, 129, 1);
    return 0;
}
fn main() -> u64 {
    p := rt_alloc(8);
    raw_store(p, 0);
    h := rt_thread_spawn(producer, p);
    mut seen = 0;
    while seen == 0 {
        value := raw_atomic_load(p);
        if value == 7 {
            seen = 1;
        } else {
            rt_syscall(202, p, 128, value);
        }
    }
    rt_thread_join(h);
    println(raw_load(p));
    rt_free(p);
    return 0;
}

unsafe module runtime;
fn main() -> u64 {
    hr := raw_win32(CoInitializeEx, 0, 2);
    println(hr);
    out := rt_alloc(8);
    raw_store(out, 0);
    println(raw_win_local(grail_com_make_object, out));
    obj := raw_load(out);
    vt := raw_load(obj);
    qi := raw_load(vt);
    add := raw_load(vt + 8);
    rel := raw_load(vt + 16);
    println(raw_win_call(add, obj));
    println(raw_win_call(add, obj));
    println(raw_win_call(rel, obj));
    println(raw_win_call(rel, obj));
    println(raw_win_call(qi, obj, 0, out));
    println(raw_win_call(qi, obj, 0, out));
    zero := rt_alloc(16);
    raw_store(zero, 0);
    raw_store(zero + 8, 0);
    println(raw_win_call(qi, obj, zero, out));
    iid := raw_win_local(grail_com_iid_address);
    raw_store(out, 0);
    println(raw_win_call(qi, obj, iid, out));
    println(raw_load(out) - obj);
    println(raw_win_call(rel, obj));
    println(raw_win_call(rel, obj));
    raw_win32(CoUninitialize);
    rt_free(out);
    rt_free(zero);
    return 0;
}
